import tripol.discord

func answer(m:discord.Message)->string {
    if m.matches("hola") {return m.reply("¡Hola, " + m.author_id + "!")}
    return ""
}
bot = discord.bot()
bot.on_message(&answer)
show bot.preview_event("{\"op\":0,\"t\":\"MESSAGE_CREATE\",\"d\":{\"channel_id\":\"123\",\"content\":\"hola\",\"author\":{\"id\":\"456\"}}}")

func greet(name="Guest", score=10)->string {
    return f"Hello {name}, your score is {score}"
}
show greet()
show greet("Alice", 25)

total=0
repeat 1000 {
    scratch {
        values=ints(65535)
        values[0]=7
        total+=values[0]
    }
}
show total

a = ints(3)
for i in range(3) {
    a[i] = i * 2
}
show a, sum(a)

score = 80
if score >= 60 {
    show "Passed"
}

score = 75
if score >= 90 {
    show "Excellent"
} else if score >= 60 {
    show "Passed"
} else {
    show "Try again"
}

age = 16
allowed = true
if age >= 13 and allowed {
    show "Welcome"
} else {
    show "Unavailable"
}

a = 10
b = 0
try {
    show a / b
} catch code {
    show code
}

try {
    throw 101
} catch code {
    show code
} finally {
    show "Finished"
}

func add(a:int, b:int)->int {
    return a + b
}
show add(4, 5)

func greet(name="Guest")->string {
    return "Hello " + name
}
show greet()
show greet("Ada")

func greet(name:string)->string {
    return "Hola, " + name
}

func apply(handler:func(string)->string,name:string)->string {
    return handler(name)
}

show apply(&greet, "Ada")

for i in range(1, 4) {
    show i
}

numbers = [10, 20, 30]
for i, value in numbers {
    show i, value
}

n = 0
while n < 3 {
    n += 1
}
show n

total = 0
repeat 3 {
    total += 2
}
show total

for i in range(5) {
    if i == 2 {continue}
    if i == 4 {break}
    show i
}

total = 0
repeat 3 {
    scratch {
        values = ints(100)
        values[0] = 7
        total += values[0]
    }
}
show total

func double(n:int)->int {
    return n * 2
}

a = 10
b = 0
if b != 0 {
    show a / b
} else {
    show "Cannot divide by zero"
}
